{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { colName, colIndex, compareAddr } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const rest = s.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  const key = am[1].toUpperCase() + Number(am[2])
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { col: colIndex(am[1].toUpperCase()), row: Number(am[2]), content: rest, key })
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out += `${c.key}=${sheet.format(sheet.get(c.key))}\n`
} else {
  for (const c of sorted) {
    let line = `${c.key}:`
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) {
        const set = new Map()
        const add = (col, row) => set.set(col * 1000 + row, { col, row })
        for (const r of p.refs) {
          if (r.type === 'ref') {
            if (r.a) add(r.a.col, r.a.row)
          } else if (r.a && r.b) {
            for (let x = Math.min(r.a.col, r.b.col); x <= Math.max(r.a.col, r.b.col); x++)
              for (let y = Math.min(r.a.row, r.b.row); y <= Math.max(r.a.row, r.b.row); y++) add(x, y)
          }
        }
        for (const v of [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row))
          line += ` ${colName(v.col)}${v.row}`
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

