{"file_path":"src/addr.js","content":"export function colIndex(s) {
  // A=1..Z=26, AA=27..ZZ=702
  let n = 0
  for (const ch of s) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const m = n - 27
  return String.fromCharCode(65 + Math.floor(m / 26) + 0) + String.fromCharCode(65 + (m % 26))
}

export function compareAddr(a, b) {
  return a.col - b.col || a.row - b.row
}

// Returns {col,row} or null when the word is not an addressable cell.
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}
"}

