{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { colName, colIndex, compareAddr } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const rest = s.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  const key = am[1].toUpperCase() + Number(am[2])
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { col: colIndex(am[1].toUpperCase()), row: Number(am[2]), content: rest, key })
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out += `${c.key}=${sheet.format(sheet.get(c.key))}\n`
} else {
  for (const c of sorted) {
    let line = `${c.key}:`
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) {
        const set = new Map()
        const add = (col, row) => set.set(col * 1000 + row, { col, row })
        for (const r of p.refs) {
          if (r.type === 'ref') {
            if (r.a) add(r.a.col, r.a.row)
          } else if (r.a && r.b) {
            for (let x = Math.min(r.a.col, r.b.col); x <= Math.max(r.a.col, r.b.col); x++)
              for (let y = Math.min(r.a.row, r.b.row); y <= Math.max(r.a.row, r.b.row); y++) add(x, y)
          }
        }
        for (const v of [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row))
          line += ` ${colName(v.col)}${v.row}`
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/addr.js","content":"export function colIndex(s) {
  // A=1..Z=26, AA=27..ZZ=702
  let n = 0
  for (const ch of s) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const m = n - 27
  return String.fromCharCode(65 + Math.floor(m / 26) + 0) + String.fromCharCode(65 + (m % 26))
}

export function compareAddr(a, b) {
  return a.col - b.col || a.row - b.row
}

// Returns {col,row} or null when the word is not an addressable cell.
export function parseAddr(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}
"}

{"file_path":"src/parse.js","content":"import { parseAddr } from './addr.js'

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^():,])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

const CMP = new Set(['=', '<>', '<', '<=', '>', '>='])

// Returns {ok:false} or {ok:true, ast, refs}
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return { ok: false }
  let p = 0
  const refs = []
  let badRange = false
  const fail = () => { throw new Error('syntax') }
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v

  function cmp() {
    let l = add()
    while (toks[p] && toks[p].t === 'op' && CMP.has(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { type: 'neg', op, e: unary() }
    }
    return primary()
  }
  function args() {
    const list = []
    if (isOp(')')) { p++; return list }
    for (;;) {
      list.push(expr(true))
      if (isOp(',')) { p++; continue }
      if (isOp(')')) { p++; return list }
      fail()
    }
  }
  function expr(direct) {
    const start = p
    const n = cmp()
    if (n.type === 'range' && !direct) badRange = true
    return n
  }
  function primary() {
    const t = toks[p]
    if (!t) fail()
    if (t.t === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      if (e.type === 'range') badRange = true
      return { type: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        return { type: 'call', name: up, args: args() }
      }
      if (isOp(':') && toks[p + 1] && toks[p + 1].t === 'word') {
        const w2 = toks[p + 1].v
        p += 2
        const a = parseAddr(t.v), b = parseAddr(w2)
        refs.push({ type: 'range', a, b })
        return { type: 'range', a, b }
      }
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      const a = parseAddr(t.v)
      refs.push({ type: 'ref', a })
      return { type: 'ref', a }
    }
    fail()
  }

  try {
    const ast = cmp()
    if (p !== toks.length) fail()
    // ranges outside direct argument position
    if (ast.type === 'range') badRange = true
    if (hasBadRange(ast)) badRange = true
    return { ok: true, ast, refs, badRange }
  } catch (e) {
    if (e.message === 'syntax') return { ok: false }
    throw e
  }
}

function hasBadRange(n) {
  switch (n.type) {
    case 'range': return true
    case 'bin': return hasBadRange(n.l) || hasBadRange(n.r)
    case 'neg': case 'paren': return hasBadRange(n.e)
    case 'call': return n.args.some((a) => (a.type === 'range' ? false : hasBadRange(a)))
    default: return false
  }
}
"}

