{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ k: 'err', v: e })
const num = (v) => (Number.isFinite(v) ? { k: 'num', v } : err('#DIV/0!'))
const ZERO = { k: 'num', v: 0 }

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const RANK = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.k !== b.k) return RANK[a.k] - RANK[b.k]
  if (a.k === 'text') return cpCompare(a.v, b.v)
  if (a.k === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return { k: 'num', v: v.v ? 1 : 0 }
  return err('#VALUE!')
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  format(v) {
    if (v.k === 'num') return String(Number(v.v.toPrecision(10)))
    if (v.k === 'bool') return v.v ? 'TRUE' : 'FALSE'
    return v.v
  }

  get(key) {
    const cell = this.cells.get(key)
    if (!cell) return ZERO
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    let r
    try {
      r = this.compute(cell.content)
    } finally {
      this.busy.delete(key)
    }
    this.memo.set(key, r)
    return r
  }

  compute(c) {
    if (c[0] === '=') {
      const p = parseFormula(c.slice(1))
      if (!p.ok || p.badRange) return err('#ERR!')
      return this.ev(p.ast)
    }
    if (c === '') return ZERO
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return { k: 'num', v: Number(c) }
    if (ERRORS.has(c)) return err(c)
    return { k: 'text', v: c }
  }

  cellAt(a) {
    if (!a) return err('#REF!')
    return null
  }

  ref(a) {
    return this.get(this.keyOf(a))
  }

  keyOf(a) {
    let col = a.col
    let name
    if (col <= 26) name = String.fromCharCode(64 + col)
    else {
      const m = col - 27
      name = String.fromCharCode(65 + Math.floor(m / 26)) + String.fromCharCode(65 + (m % 26))
    }
    return name + a.row
  }

  expand(n) {
    if (!n.a || !n.b) return [err('#REF!')]
    const out = []
    for (let x = Math.min(n.a.col, n.b.col); x <= Math.max(n.a.col, n.b.col); x++)
      for (let y = Math.min(n.a.row, n.b.row); y <= Math.max(n.a.row, n.b.row); y++)
        out.push(this.ref({ col: x, row: y }))
    return out
  }

  ev(n) {
    switch (n.type) {
      case 'num': return { k: 'num', v: n.v }
      case 'bool': return { k: 'bool', v: n.v }
      case 'paren': return this.ev(n.e)
      case 'ref': return n.a ? this.ref(n.a) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'neg': {
        const v = this.ev(n.e)
        if (v.k === 'err') return v
        const x = toNum(v)
        if (x.k === 'err') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.k === 'err') return l
    const r = this.ev(n.r)
    if (r.k === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const d = compare(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { k: 'bool', v: res }
    }
    const a = toNum(l)
    if (a.k === 'err') return a
    const b = toNum(r)
    if (b.k === 'err') return b
    switch (n.op) {
      case '+': return num(a.v + b.v)
      case '-': return num(a.v - b.v)
      case '*': return num(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : num(a.v / b.v)
      case '^': return num(Math.pow(a.v, b.v))
    }
    return err('#ERR!')
  }

  call(n) {
    const name = n.name
    const argc = n.args.length
    const multi = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (multi.includes(name)) {
      if (argc < 1) return err('#ERR!')
    } else if (name === 'ABS') {
      if (argc !== 1) return err('#ERR!')
    } else if (name === 'IF') {
      if (argc !== 3) return err('#ERR!')
    } else return err('#NAME?')

    if (name === 'IF') {
      const [c, t, f] = n.args
      if (c.type === 'range' || t.type === 'range' || f.type === 'range') return err('#VALUE!')
      const cv = this.ev(c)
      if (cv.k === 'err') return cv
      let truth
      if (cv.k === 'bool') truth = cv.v
      else if (cv.k === 'num') truth = cv.v !== 0
      else return err('#VALUE!')
      return this.ev(truth ? t : f)
    }

    const vals = []
    for (const a of n.args) {
      if (a.type === 'range') vals.push(...this.expand(a))
      else vals.push(this.ev(a))
    }
    const e = vals.find((v) => v.k === 'err')
    if (e) return e
    if (name === 'COUNT') return { k: 'num', v: vals.filter((v) => v.k === 'num').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'err') return x
      nums.push(x.v)
    }
    if (name === 'ABS') return nums.length === 1 ? num(Math.abs(nums[0])) : err('#VALUE!')
    if (name === 'SUM') return num(nums.reduce((s, x) => s + x, 0))
    if (name === 'MIN') return num(Math.min(...nums))
    if (name === 'MAX') return num(Math.max(...nums))
    return num(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
}
